import React from "react";

// الشعار الرسمي الأصلي لمكتب سعود أحمد الشحي للمحاماة والاستشارات القانونية
// تم استخراجه من ملف الهوية البصرية المعتمد (وضع خلفية شفافة) وتضمينه هنا مباشرة
// لضمان مطابقة الشعار المعروض في النظام بنسبة 100% للشعار الرسمي المعتمد.
const EMBLEM_SRC =
  "data:image/webp;base64,";
const FULL_LOGO_SRC =
  "data:image/webp;base64,";

interface LogoProps {
  variant?: "full" | "horizontal" | "emblem";
  mode?: "light" | "dark"; // light background or dark background
  className?: string;
  size?: "sm" | "md" | "lg" | "xl";
}

// شارة الشعار (الميزان + السنابل + العمود) فقط بدون النص - تُستخدم داخلياً وفي الأماكن المدمجة
export const FirmEmblemSVG: React.FC<{ mode?: "light" | "dark"; className?: string }> = ({
  className = "w-16 h-16",
}) => {
  return (
    <img
      src={EMBLEM_SRC}
      alt="شعار مكتب سعود أحمد الشحي للمحاماة والاستشارات القانونية"
      className={`${className} object-contain select-none`}
      draggable={false}
    />
  );
};

export const Logo: React.FC<LogoProps> = ({
  variant = "full",
  mode = "light",
  className = "",
  size = "md",
}) => {
  const isDark = mode === "dark";
  const tealClass = isDark ? "text-teal-300" : "text-[#0c4a47]";
  const goldClass = isDark ? "text-amber-200" : "text-[#b89b6a]";

  const emblemSizes = {
    sm: "w-8 h-8",
    md: "w-12 h-12",
    lg: "w-20 h-20",
    xl: "w-32 h-32",
  };

  const fullSizes = {
    sm: "w-28",
    md: "w-40",
    lg: "w-56",
    xl: "w-72",
  };

  if (variant === "emblem") {
    return <FirmEmblemSVG mode={mode} className={`${emblemSizes[size]} ${className}`} />;
  }

  if (variant === "horizontal") {
    return (
      <div className={`flex items-center gap-3 ${className}`} dir="rtl">
        <FirmEmblemSVG mode={mode} className={`${emblemSizes[size]} shrink-0`} />
        <div className="flex flex-col text-right leading-tight">
          <span className={`font-black tracking-tight text-base sm:text-lg ${tealClass}`}>
            سعود أحمد الشحي
          </span>
          <span className={`text-[11px] sm:text-xs font-bold ${goldClass}`}>
            للمحاماة والاستشارات القانونية
          </span>
          <span className="text-[9px] font-semibold tracking-wider text-slate-400 mt-0.5">
            SUOOD AHMED ALSHEHHI
          </span>
        </div>
      </div>
    );
  }

  // Full Variant - الشعار الرسمي الكامل (الشارة + الاسم بالخط الأصلي) كصورة واحدة مطابقة للهوية المعتمدة
  return (
    <div className={`flex flex-col items-center text-center select-none ${className}`} dir="rtl">
      <img
        src={FULL_LOGO_SRC}
        alt="شعار مكتب سعود أحمد الشحي للمحاماة والاستشارات القانونية - Suood Ahmed Alshehhi Advocates & Legal Consultants"
        className={`${fullSizes[size]} object-contain select-none`}
        draggable={false}
      />
    </div>
  );
};

export default Logo;
